def search(arr, n):
    left, right = 0, n - 1
    while left < right:
        mid = left + (right - left) // 2
        if mid % 2 == 1:
            mid -= 1
        if arr[mid] == arr[mid + 1]:
            left = mid + 2
        else:
            right = mid
    return arr[left]

def check_triplet(A, n, sum, count):
    A.sort()
    for i in range(n - 2):
        left = i + 1
        right = n - 1
        while left < right:
            if A[i] + A[left] + A[right] == sum:
                return True
            elif A[i] + A[left] + A[right] < sum:
                left += 1
            else:
                right -= 1
    return False

