    n_digits = len(x_str)
    digits = [int(d) for d in x_str]
    while True:
        next_term = sum(digits)
        if next_term == x:
            return True
        elif next_term > x:
            return False
        digits.pop(0)
        digits.append(next_term)

def common_prefix(arr, n):
    if not arr:
        return ""
    prefix = arr[0]
    for i in range(1, n):
        while arr[i].find(prefix) != 0:
            prefix = prefix[:-1]
            if not prefix:
                return ""
    return prefix

def count_pairs(arr, n, k):
    arr_set = set(arr)
    count = 0
    seen = set()
    for num in arr_set:
        if num + k in arr_set and num not in seen:
            count += 1
            seen.update([num, num + k])
        if num - k in arr_set and num - k not in seen:
            count += 1
            seen.update([num, num - k])
    return count

