    while low <= high:
        if A[low] <= A[high]:
            return low
        mid = (low + high) // 2
        next_idx = (mid + 1) % len(A)
        prev_idx = (mid - 1 + len(A)) % len(A)
        if A[mid] <= A[next_idx] and A[mid] <= A[prev_idx]:
