    i = len(n) - 2
    while i >= 0 and n[i] >= n[i + 1]:
        i -= 1
    if i == -1:
        return False
    j = len(n) - 1
    while n[j] <= n[i]:
        j -= 1
    n[i], n[j] = n[j], n[i]
    n = n[:i + 1] + sorted(n[i + 1:])
