def join_tuples(test_list):
    result = []
    temp_dict = {}
    for tpl in test_list:
        if tpl[0] not in temp_dict:
            temp_dict[tpl[0]] = list(tpl)
        else:
            temp_dict[tpl[0]].extend(tpl[1:])
    for key, val in temp_dict.items():
        result.append(tuple(val))
    return result

def maximum_segments(n, a, b, c):
    if n == 0:
        return 0
    if n < 0:
        return -float('inf')
    return max(1 + maximum_segments(n - a, a, b, c),
               1 + maximum_segments(n - b, a, b, c),
               1 + maximum_segments(n - c, a, b, c))

def min_sum_path(A):
    n = len(A)
    for i in range(n-2, -1, -1):
        for j in range(len(A[i])):
            A[i][j] += min(A[i+1][j], A[i+1][j+1])
    return A[0][0]
